curl --fail-with-body -X GET https://openaliment.ro/api/v2/manage/audit-events/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa \
  -H 'Accept: application/json' \
  -H 'Authorization: Bearer YOUR_ACCESS_TOKEN'
```

