import json, urllib.request, urllib.parse, urllib.error

headers = {'Accept': 'application/json', 'Authorization': 'Bearer YOUR_ACCESS_TOKEN', 'Idempotency-Key': 'exemplu-manageImportStream-001', 'Content-Type': 'application/x-ndjson'}
data = '{"schema_version":"openaliment.transfer.stream.v1","source_base_url":"https://exemplu.example","exported_at":"2026-10-25T00:00:00Z"}\n{"end":true,"records":0,"sha256":"6ccc0da298e61d45a94621c2eade47a5d709f8d2117828dd1abaff6f9c92825b"}\n'.encode("utf-8")
request = urllib.request.Request('https://openaliment.ro/api/v2/manage/import-stream', data=data, headers=headers, method='POST')
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        print(json.load(response))
except urllib.error.HTTPError as error:
    print(error.code, error.read().decode("utf-8", errors="replace"))
    raise
